      {active === "alerts" && <Detail title="Active alerts" subtitle="Triggers raised from evidence-backed changes in the current monitoring window." type="alerts" />}
      {active === "evidence" && <Detail title="Evidence library" subtitle="Every published claim carries a source tier, matched text and retrieval timestamp." type="evidence" />}
      {active === "methodology" && <Methodology />}
