function NavItem({ icon, label, active, count, onClick }: { icon: string; label: string; active?: boolean; count?: string; onClick: () => void }) { return <button className={`nav-item ${active ? "active" : ""}`} onClick={onClick}><Icon name={icon}/><span>{label}</span>{count && <b>{count}</b>}</button>; }

function Methodology() {
  return <div className="detail-page"><div className="hero detail-hero"><div><div className="eyebrow accent">METHOD / RECOMPUTABLE RULES</div><h2>How the intelligence is built</h2><p>Every rendered number should trace to a SignalAtom, a source excerpt and a versioned rule.</p></div><div className="detail-pill">Brief v1.0 · 07 Sep 2026</div></div><div className="method-grid"><section className="method-panel"><div className="eyebrow accent">EVIDENCE STATES</div><h3>How sources behave</h3><div className="method-row"><EvidenceBadge state="ESTABLISHED"/><p>Primary T0/T1 source plus an independent source tracing to different underlying reporting. Full dial weight.</p></div><div className="method-row"><EvidenceBadge state="SUPPORTED"/><p>One primary source, or corroboration only from analyst/anonymous reporting. Dial weight 0.6; headline must say “reported” or “the filing states.”</p></div><div className="method-row"><EvidenceBadge state="CONTESTED"/><p>On-record disagreement or contrary data. Show the conflict and a Resolve This block.</p></div><div className="method-row"><EvidenceBadge state="HYPOTHESIS"/><p>No primary source. Never moves a dial and cannot enter the published insight set.</p></div></section><section className="method-panel"><div className="eyebrow accent">DIAL MOVEMENT</div><h3>Deterministic computation</h3><div className="formula-box">daily change = Σ sign × magnitude × evidence weight</div><p className="method-copy">Evidence weights are 1.0 / 0.6 / 0.3 / 0.0 for Established / Supported / Contested / Hypothesis. Dials are bounded 0–100 and decay toward the trailing 90-day mean.</p><div className="method-rule"><span>Roadmap / government</span><strong>45-day half-life</strong></div><div className="method-rule"><span>Share / customer</span><strong>30-day half-life</strong></div><div className="method-rule"><span>Duplicates</span><strong>same event + 7d + cosine &gt; .85</strong></div></section><section className="method-panel"><div className="eyebrow accent">RANKING</div><h3>Why an insight appears first</h3><div className="formula-box">impact × evidence × relevance × freshness</div><p className="method-copy">The displayed rank score is recomputable from the visible components. Capacity and customer atoms receive the highest strategic-impact weights; stale evidence decays exponentially.</p><div className="method-rule"><span>Impact</span><strong>1–5</strong></div><div className="method-rule"><span>Relevance</span><strong>0–100</strong></div><div className="method-rule"><span>Freshness</span><strong>e<sup>−age / half-life</sup></strong></div></section><section className="method-panel"><div className="eyebrow accent">PUBLISH GATES</div><h3>What can reach the brief</h3><ul className="method-list"><li>Matched excerpt contains the claimed value.</li><li>URL is live and source scope matches the claim.</li><li>No analyst inference is attributed as external fact.</li><li>Every number has a linked atom and source detail.</li><li>Stale, unresolved, or excluded claims appear in caveats.</li></ul></section></div></div>;
}

